const $=s=>document.querySelector(s), app=$('#app');
const money=n=>'₹'+n.toLocaleString('en-IN');
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage={get(k,f){try{return JSON.parse(localStorage.getItem('buildlab-'+k))??f}catch{return f}},set(k,v){try{localStorage.setItem('buildlab-'+k,JSON.stringify(v))}catch{toast('Browser storage unavailable. Changes last for this visit.')}}};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
let tab=['creator','tickets','room'].includes(location.hash.slice(1))?location.hash.slice(1):'creator',savedLesson=storage.get('lesson',null);
const lessons={space:{title:'A small planet. A big neighbourhood.',text:'Our solar system has one star, the Sun, and eight planets. Gravity keeps each planet moving in an orbit around the Sun. Earth takes about 365 days to complete one orbit. A planet closer to the Sun usually has a shorter year.',activity:'Become a solar-system designer: draw an imaginary planet, name it, and decide how long its year lasts. Explain how its distance from its star might affect its orbit.',question:'What keeps the planets in orbit around the Sun?',answers:['Gravity','Sound waves','Clouds','Magnetised roads'],correct:0,why:'Gravity pulls planets towards the Sun while their forward motion keeps them orbiting.'},climate:{title:'Your everyday climate superpowers.',text:'The greenhouse effect helps keep Earth warm enough for life. Gases such as carbon dioxide absorb and re-emit heat. Adding more greenhouse gases can warm the planet. Saving energy, reducing waste and choosing lower-emission travel can help reduce our impact.',activity:'Run a classroom energy audit: list five devices, estimate how long they run, and suggest one practical way to save electricity.',question:'Which action can reduce energy use?',answers:['Leaving lights on','Switching off unused devices','Opening a running fridge','Running empty washing cycles'],correct:1,why:'Switching off devices when they are not needed reduces wasted electricity.'},fractions:{title:'A pizza party with a mathematical twist.',text:'A fraction describes equal parts of a whole. The denominator tells you how many equal parts the whole is split into. The numerator tells you how many parts you have. If a pizza has eight equal slices and you take two, you have 2/8 of the pizza — the same amount as 1/4.',activity:'Design a pizza with eight equal slices. Give half to a friend and one quarter to yourself. How many slices remain? Explain your answer with a drawing.',question:'Which fraction is equal to 2/8?',answers:['1/2','2/4','1/4','3/8'],correct:2,why:'Divide both the numerator and denominator of 2/8 by 2 to get 1/4.'}};
let lesson=savedLesson||{...lessons.space,grade:'6',topic:'space'};
function shell(side,body){app.innerHTML=`<div class="demo"><aside class="sidebar">${side}</aside><div class="workspace">${body}</div></div>`}
function creator(){shell(`<span class="tiny">THE AI APPS & AGENTS TRACK</span><h2>Big ideas.<br>Bite-sized lessons.</h2><p>You're the teacher. Choose a topic, make a mini lesson, then put your knowledge to the test.</p><label for="grade">Who are we teaching?</label><select id="grade">${[6,7,8,9,10].map(g=>`<option ${lesson.grade==g?'selected':''}>${g}</option>`).join('')}</select><label for="topic">Pick your curiosity</label><select id="topic"><option value="space">🪐 The solar system</option><option value="climate">🌱 Climate & energy</option><option value="fractions">🍕 Fantastic fractions</option></select><button class="button dark" id="generate">✦ Create a sample lesson</button><p class="note">Demo mode · Curated sample content, not a live AI model. Grade changes add a different challenge. Edit the lesson and save your draft on this device.</p><div class="project-tag">YOUR BUILD CHALLENGE<br>Connect a model API. Add teacher review. Save drafts to a database.</div>`,`<div class="workspace-top"><strong>✳ Digital Creator Studio</strong><span class="badge">YOUR EDITABLE PREVIEW</span></div><div id="lesson"></div>`);$('#topic').value=lesson.topic;drawLesson();$('#generate').onclick=()=>{const topic=$('#topic').value,grade=$('#grade').value;lesson={...lessons[topic],topic,grade};drawLesson();toast('Lesson ready. Edit it, then try the quiz!')}}
function drawLesson(){const challenge=Number(lesson.grade)>=9?'Builder challenge: identify an assumption in this lesson and design a way to test it.':Number(lesson.grade)>=7?'Builder challenge: explain the main idea using an example from your own life.':'Starter challenge: draw the main idea and explain it to a friend.';$('#lesson').innerHTML=`<article class="lesson"><span class="tiny">GRADE ${safe(lesson.grade)} · 5-MINUTE MINI LESSON</span><h3 class="lesson-title" contenteditable="true" role="textbox" aria-label="Edit lesson title">${safe(lesson.title)}</h3><p id="lesson-text" contenteditable="true" role="textbox" aria-label="Edit lesson text">${safe(lesson.text)}</p><div class="callout"><b>TRY THIS →</b><br>${safe(lesson.activity)}<br><br>${challenge}</div><div class="quiz"><h4>Quick check · ${safe(lesson.question)}</h4><div class="answers">${lesson.answers.map((a,i)=>`<button data-answer="${i}">${String.fromCharCode(65+i)}. ${safe(a)}</button>`).join('')}</div><p class="feedback" aria-live="polite">Pick an answer to see how you did.</p></div><div class="action-row"><button class="secondary" id="save-lesson">↓ Save draft</button><button class="secondary" id="download-lesson">↗ Download lesson</button></div></article>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const correct=+b.dataset.answer===lesson.correct;b.classList.add(correct?'correct':'wrong');$('.feedback').textContent=correct?'✓ Exactly! '+lesson.why:'Not quite — try again. Think about the main idea above.';if(correct)document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true)});const capture=()=>{lesson.title=$('.lesson-title').textContent;lesson.text=$('#lesson-text').textContent};$('#save-lesson').onclick=()=>{capture();storage.set('lesson',lesson);toast('Draft saved on this browser.')};$('#download-lesson').onclick=()=>{capture();download('buildlab-lesson.txt',`${lesson.title}\nGrade ${lesson.grade}\n\n${lesson.text}\n\nActivity: ${lesson.activity}\n\n${lesson.question}\n${lesson.answers.map((a,i)=>`${i+1}. ${a}`).join('\n')}\n\nAnswer: ${lesson.answers[lesson.correct]}\n${lesson.why}`)}}
function download(name,content){const url=URL.createObjectURL(new Blob([content],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const shows={cosmic:{name:'Cosmic Beats',icon:'🌌',subtitle:'An imaginary interstellar music night',time:'Friday · 6:00 PM',price:350},comedy:{name:'Laugh Lab',icon:'🎤',subtitle:'An imaginary student comedy showcase',time:'Saturday · 5:00 PM',price:250},drama:{name:'The Time Traveller',icon:'🎭',subtitle:'An imaginary adventure on stage',time:'Sunday · 4:00 PM',price:300}};
let show='cosmic',selected=new Set(),bookings=storage.get('bookings',{});
function tickets(){const s=shows[show];shell(`<span class="tiny">THE WEB APPS TRACK</span><h2>Your night.<br>Your front row.</h2><p>Pick a show, find your favourite seats, and make a demo booking.</p><label for="show">What's your scene?</label><select id="show">${Object.entries(shows).map(([k,v])=>`<option value="${k}" ${show===k?'selected':''}>${v.icon} ${v.name}</option>`).join('')}</select><label>Show details</label><p>${safe(s.subtitle)}<br><b>${s.time}</b></p><div class="callout">${money(s.price)} per seat<br>Pick up to 6 seats. All seats have the same price.</div><button class="secondary" id="reset-bookings">Reset this show's demo bookings</button><p class="note">Simulation only · No payment or real ticket. Bookings persist in this browser and sync across its tabs. Other devices have separate bookings.</p><div class="project-tag">YOUR BUILD CHALLENGE<br>Add a database and an API that prevents two people booking the same seat.</div>`,`<div class="workspace-top"><strong>${s.icon} ${s.name}</strong><span class="badge">INTERACTIVE SEAT MAP</span></div><div class="stage">THE STAGE</div><div class="seats" aria-label="Choose your seats">${'ABCDE'.split('').map((row,r)=>`<span class="row-label">${row}</span>${Array.from({length:8},(_,i)=>{const id=row+(i+1),taken=(bookings[show]||[]).includes(id)||['A3','A4','B6','C2','D7'].includes(id);return `<button class="seat ${selected.has(id)?'selected':''}" data-seat="${id}" ${taken?'disabled':''} aria-label="Seat ${id}${taken?', booked':''}" aria-pressed="${selected.has(id)}">${id}</button>`}).join('')}`).join('')}</div><div class="legend"><span><i></i>Available</span><span><i class="sel"></i>Your pick</span><span><i class="booked"></i>Booked</span></div><div class="ticket-summary"><span id="selection-text"></span><b id="total"></b></div><button class="button dark" id="book" style="width:100%;margin-top:14px">Confirm demo booking ↗</button><div id="confirmation" aria-live="polite"></div>`);$('#show').onchange=e=>{show=e.target.value;selected.clear();tickets()};$('#reset-bookings').onclick=()=>{bookings[show]=[];storage.set('bookings',bookings);selected.clear();tickets();toast('Demo bookings reset for this show.')};document.querySelectorAll('[data-seat]').forEach(b=>b.onclick=()=>{const id=b.dataset.seat;if(selected.has(id))selected.delete(id);else if(selected.size<6)selected.add(id);else return toast('Choose up to 6 seats per booking.');b.classList.toggle('selected',selected.has(id));b.setAttribute('aria-pressed',selected.has(id));updateTotal()});$('#book').onclick=()=>{if(!selected.size)return toast('Choose a seat first.');bookings=storage.get('bookings',bookings);if([...selected].some(x=>(bookings[show]||[]).includes(x))){selected.clear();tickets();return toast('A seat was just booked in another tab. Please choose again.')}const seats=[...selected],total=seats.length*s.price;bookings[show]=[...(bookings[show]||[]),...seats];storage.set('bookings',bookings);selected.clear();tickets();$('#confirmation').innerHTML=`<div class="success-panel"><b>✓ You're on the guest list. (Pretend, of course.)</b><br>${safe(s.name)} · Seats ${seats.join(', ')} · ${money(total)}<br>These seats now stay booked when you revisit this browser.</div>`;toast('Demo booking confirmed!')};updateTotal()}
function updateTotal(){$('#selection-text').textContent=selected.size?'Your seats: '+[...selected].join(', '):'Pick your seats above';$('#total').textContent=money(selected.size*shows[show].price);$('#book').disabled=!selected.size;$('#book').style.opacity=selected.size?1:.5}
window.addEventListener('storage',e=>{if(e.key==='buildlab-bookings'){bookings=storage.get('bookings',{});if(tab==='tickets'){selected.clear();tickets()}}});
const items={bed:{name:'Cosy bed',icon:'🛏️',cost:12000,x:24,y:57},desk:{name:'Study desk',icon:'🪑',cost:6500,x:68,y:59},plant:{name:'Green friend',icon:'🪴',cost:1200,x:79,y:29},lamp:{name:'Warm lamp',icon:'💡',cost:1800,x:22,y:19},art:{name:'Wall art',icon:'🖼️',cost:2500,x:30,y:12},rug:{name:'Soft rug',icon:'🟫',cost:3000,x:50,y:70}};
let room=storage.get('room',{wall:'#e3d7c5',budget:25000,active:['bed','plant','desk'],positions:{}});
function roomDemo(){shell(`<span class="tiny">THE PRODUCT DEVELOPMENT TRACK</span><h2>A little space.<br>A lot of you.</h2><p>Build your happy place. Pick a palette, add furniture, and move it around to make it yours.</p><label>Set the mood · Wall colour</label><div class="swatches">${['#e3d7c5','#c6d6bb','#bacdd7','#dac6d5','#eee4b7'].map((c,i)=>`<button class="swatch ${room.wall===c?'active':''}" data-colour="${c}" style="background:${c}" aria-label="${['Sand','Sage','Sky','Lavender','Butter'][i]} wall colour" aria-pressed="${room.wall===c}"></button>`).join('')}</div><label for="budget">Your budget: <span id="budget-value"></span></label><input id="budget" type="range" min="10000" max="50000" step="1000" value="${room.budget}"><label>Make room for your favourites</label><div class="furniture">${Object.entries(items).map(([k,v])=>`<button data-item="${k}" class="${room.active.includes(k)?'active':''}" aria-pressed="${room.active.includes(k)}">${v.icon} ${v.name}<br><small>${money(v.cost)}</small></button>`).join('')}</div><p class="note">Illustrative prices · A playful 2D layout, not a scale floor plan. Drag items, or focus one and use arrow keys.</p><div class="project-tag">YOUR BUILD CHALLENGE<br>Interview a user. Add real dimensions, a product catalogue, and layout sharing.</div>`,`<div class="workspace-top"><strong>⌂ Dream Room Studio</strong><span class="badge">DESIGNED BY YOU</span></div><div class="room-scene" style="--wall:${room.wall}" aria-label="Interactive room layout"><div class="window"></div><div id="objects"></div></div><div class="room-stats"><span>Your room total<br><strong id="room-total"></strong></span><span>Budget left<br><strong id="room-left"></strong></span></div><div class="budget-meter"><span></span></div><p class="budget-alert" aria-live="polite"></p><div class="action-row"><button class="secondary" id="save-room">↓ Save my room</button><button class="secondary" id="export-room">↗ Download plan</button><button class="secondary" id="reset-room">Start over</button></div>`);document.querySelectorAll('[data-colour]').forEach(b=>b.onclick=()=>{room.wall=b.dataset.colour;$('.room-scene').style.setProperty('--wall',room.wall);document.querySelectorAll('[data-colour]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)})});$('#budget').oninput=e=>{room.budget=+e.target.value;roomTotals()};document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const id=b.dataset.item;room.active=room.active.includes(id)?room.active.filter(x=>x!==id):[...room.active,id];b.classList.toggle('active',room.active.includes(id));b.setAttribute('aria-pressed',room.active.includes(id));drawObjects();roomTotals()});$('#save-room').onclick=()=>{storage.set('room',room);toast('Your room is saved on this browser.')};$('#reset-room').onclick=()=>{room={wall:'#e3d7c5',budget:25000,active:['bed','plant','desk'],positions:{}};roomDemo()};$('#export-room').onclick=()=>download('my-dream-room.txt',`MY DREAM ROOM\nWall: ${room.wall}\nBudget: ${money(room.budget)}\n${room.active.map(k=>`${items[k].name}: ${money(items[k].cost)} · position ${Math.round((room.positions[k]||items[k]).x)}%, ${Math.round((room.positions[k]||items[k]).y)}%`).join('\n')}\nTotal: ${money(room.active.reduce((s,k)=>s+items[k].cost,0))}\nIllustrative prices only.`);drawObjects();roomTotals()}
function roomTotals(){const total=room.active.reduce((s,k)=>s+items[k].cost,0),left=room.budget-total;$('#budget-value').textContent=money(room.budget);$('#room-total').textContent=money(total);$('#room-left').textContent=money(left);$('#room-left').style.color=left<0?'#b64c37':'#617d36';$('.budget-meter span').style.width=Math.min(100,total/room.budget*100)+'%';$('.budget-meter span').style.background=left<0?'#cb7359':'#849f45';$('.budget-alert').textContent=left<0?'Over budget! Try removing an item or increasing your budget.':left===0?'Perfect fit — you used exactly your budget.':'Looking good. Your design is within budget.'}
function drawObjects(){$('#objects').innerHTML=room.active.map(k=>{const v=items[k],p=room.positions[k]||v;return `<div class="room-object" role="button" tabindex="0" aria-label="Move ${v.name}; drag or use arrow keys" data-object="${k}" style="left:${p.x}%;top:${p.y}%">${v.icon}</div>`}).join('');document.querySelectorAll('[data-object]').forEach(el=>{const k=el.dataset.object;function place(x,y){const scene=$('.room-scene');x=Math.max(0,Math.min(100-el.offsetWidth/scene.clientWidth*100,x));y=Math.max(0,Math.min(100-el.offsetHeight/scene.clientHeight*100,y));room.positions[k]={x,y};el.style.left=x+'%';el.style.top=y+'%'}el.onpointerdown=e=>{e.preventDefault();el.focus();el.setPointerCapture(e.pointerId);const rect=$('.room-scene').getBoundingClientRect(),r=el.getBoundingClientRect(),dx=e.clientX-r.left,dy=e.clientY-r.top;el.onpointermove=ev=>place((ev.clientX-rect.left-dx)/rect.width*100,(ev.clientY-rect.top-dy)/rect.height*100);el.onpointerup=el.onpointercancel=()=>el.onpointermove=null};el.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const p=room.positions[k]||items[k];place(p.x+(e.key==='ArrowRight'?2:e.key==='ArrowLeft'?-2:0),p.y+(e.key==='ArrowDown'?2:e.key==='ArrowUp'?-2:0))}})}
function render(){({creator,tickets,room:roomDemo})[tab]()}
document.querySelectorAll('[data-tab]').forEach((b,i,all)=>{b.onclick=()=>{tab=b.dataset.tab;history.replaceState(null,'','#'+tab);all.forEach(x=>{x.setAttribute('aria-selected',x===b);x.tabIndex=x===b?0:-1});render()};b.tabIndex=i===0?0:-1;b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length;all[n].focus();all[n].click()}}});document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.tab===tab);b.tabIndex=b.dataset.tab===tab?0:-1});render();if(['creator','tickets','room'].includes(location.hash.slice(1)))document.querySelector('#projects').scrollIntoView();
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(!['creator','tickets','room'].includes(next))return;tab=next;document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.tab===tab);b.tabIndex=b.dataset.tab===tab?0:-1});render();$('#projects').scrollIntoView()});
